def find_kth(arr1, arr2, k):
    # 確保 arr1 是較短的陣列，縮小二分搜尋範圍
    if len(arr1) > len(arr2):
        arr1, arr2 = arr2, arr1

    low, high = 0, min(k, len(arr1))

    while low <= high:
        i = (low + high) // 2
        j = k - i

        A_left = arr1[i-1] if i > 0 else float('-inf')
        A_right = arr1[i]   if i < len(arr1) else float('inf')
        B_left = arr2[j-1] if j > 0 else float('-inf')
        B_right = arr2[j]   if j < len(arr2) else float('inf')

        if A_left <= B_right and B_left <= A_right:
            return max(A_left, B_left)
        elif A_left > B_right:
            high = i - 1
        else:
            low = i + 1

# 測試
assert find_kth([2, 3, 6, 7, 9], [1, 4, 8, 10], 5) == 6
